def remplir_references_et_traces(apps, schema_editor):
    Transaction = apps.get_model("transactions", "Transaction")
    CompteBancaire = apps.get_model("transactions", "CompteBancaire")
    transactions = list(Transaction.objects.all().order_by("id"))

    # Certaines bases de démonstration contiennent des références vides ou
    # dupliquées. Elles doivent être rendues uniques AVANT l'ajout de la
    # contrainte UNIQUE, sinon la migration échoue sur SQLite comme sur
    # MySQL. On conserve la première occurrence et on suffixe les suivantes.
    toutes_references = [
        (tx.reference or "").strip()
        for tx in transactions
        if (tx.reference or "").strip()
    ]
    occurrences = {
        reference: toutes_references.count(reference)
        for reference in set(toutes_references)
    }
    references_reservees = set(toutes_references)
    references_utilisees = set()

    for tx in transactions:
        champs = []
        reference = (tx.reference or "").strip()
        if not reference:
            candidat = f"TRX-HIST-{tx.pk:08d}"
            suffixe = 1
            while candidat in references_reservees or candidat in references_utilisees:
                suffixe += 1
                candidat = f"TRX-HIST-{tx.pk:08d}-{suffixe}"[:40]
            reference = candidat
        elif occurrences.get(reference, 0) > 1 and reference in references_utilisees:
            base = reference[:34]
            suffixe = 1
            candidat = f"{base}-{tx.pk:04d}"[:40]
            while candidat in references_reservees or candidat in references_utilisees:
                suffixe += 1
                candidat = f"{base[:30]}-{tx.pk:04d}-{suffixe}"[:40]
            reference = candidat
        if tx.reference != reference:
            tx.reference = reference
            champs.append("reference")
        references_utilisees.add(reference)
        if tx.operation_id is None:
            import uuid as uuid_module

            tx.operation_id = uuid_module.uuid4()
            champs.append("operation_id")
        if not tx.devise:
            compte = None
            if tx.compte_source_id:
                compte = CompteBancaire.objects.filter(pk=tx.compte_source_id).first()
            if compte is None and tx.compte_destination_id:
                compte = CompteBancaire.objects.filter(pk=tx.compte_destination_id).first()
            tx.devise = compte.devise.code if compte and compte.devise_id else "XAF"
            champs.append("devise")
        if champs:
            tx.save(update_fields=champs)


